import z3

n_golfers = 36
n_groups = 9
n_weeks = 6
group_size = 4

# Integer variables: group[w][g] in 0..8
group = [[z3.Int(f"g_{w}_{p}") for p in range(n_golfers)] for w in range(n_weeks)]

s = z3.Solver()

# Each golfer gets a group 0..8 each week
for w in range(n_weeks):
    for p in range(n_golfers):
        s.add(group[w][p] >= 0, group[w][p] < n_groups)

# Each group has exactly 4 golfers each week
for w in range(n_weeks):
    for c in range(n_groups):
        # Count golfers in group c
        s.add(z3.Sum([z3.If(group[w][p] == c, 1, 0) for p in range(n_golfers)]) == group_size)

# No pair of golfers in same group more than once
# For each pair (p1, p2), they can be together at most once
for p1 in range(n_golfers):
    for p2 in range(p1+1, n_golfers):
        # Count weeks where they are together
        together_count = z3.Sum([z3.If(group[w][p1] == group[w][p2], 1, 0) for w in range(n_weeks)])
        s.add(together_count <= 1)

print("Starting solve...")
result = s.check()
print(f"Result: {result}")

if result == z3.sat:
    m = s.model()
    solution = []
    for w in range(n_weeks):
        for p in range(n_golfers):
            solution.append(m.evaluate(group[w][p]).as_long())
    print("Solution:", solution)
    # Verify
    # Check group sizes
    for w in range(n_weeks):
        counts = [0]*n_groups
        for p in range(n_golfers):
            counts[solution[w*36+p]] += 1
        print(f"Week {w} group sizes: {counts}")
    # Check pairs
    pair_weeks = {}
    for w in range(n_weeks):
        for c in range(n_groups):
            members = [p for p in range(n_golfers) if solution[w*36+p] == c]
            for i, p1 in enumerate(members):
                for p2 in members[i+1:]:
                    key = (min(p1,p2), max(p1,p2))
                    if key in pair_weeks:
                        print(f"ERROR: pair {key} together in weeks {pair_weeks[key]} and {w}")
                    pair_weeks[key] = w
    print(f"Total pairs covered: {len(pair_weeks)}")
else:
    print("UNSAT")
